"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/button-group.css";
import type { ComponentPropsWithRef } from "react";
import { cn } from "../../lib/cn";

export type ButtonGroupProps = ComponentPropsWithRef<"div"> & {
  orientation?: "horizontal" | "vertical";
  attached?: boolean;
};

export function ButtonGroup({ className, orientation = "horizontal", attached = false, role = "group", ...props }: ButtonGroupProps) {
  return (
    <div
      className={cn("whatiuse-button-group", className)}
      role={role}
      data-orientation={orientation}
      data-attached={attached || undefined}
      {...props}
    />
  );
}

export type ButtonGroupSeparatorProps = ComponentPropsWithRef<"span"> & {
  orientation?: "horizontal" | "vertical";
};

export function ButtonGroupSeparator({ className, orientation = "vertical", ...props }: ButtonGroupSeparatorProps) {
  return <span className={cn("whatiuse-button-group__separator", className)} role="separator" aria-orientation={orientation} {...props} />;
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-button-group { display: inline-flex; min-width: 0; align-items: center; gap: 4px; }

.whatiuse-button-group[data-orientation="vertical"] { flex-direction: column; align-items: stretch; }

.whatiuse-button-group[data-attached] { gap: 0; }

.whatiuse-button-group[data-attached][data-orientation="horizontal"] > .whatiuse-button:not(:first-child) { margin-left: -1px; }

.whatiuse-button-group[data-attached][data-orientation="horizontal"] > .whatiuse-button:not(:first-child):not(:last-child) { border-radius: 0; }

.whatiuse-button-group[data-attached][data-orientation="horizontal"] > .whatiuse-button:first-child:not(:last-child) { border-radius: var(--whatiuse-radius-control) 0 0 var(--whatiuse-radius-control); }

.whatiuse-button-group[data-attached][data-orientation="horizontal"] > .whatiuse-button:last-child:not(:first-child) { border-radius: 0 var(--whatiuse-radius-control) var(--whatiuse-radius-control) 0; }

.whatiuse-button-group[data-attached][data-orientation="vertical"] > .whatiuse-button:not(:first-child) { margin-top: -1px; }

.whatiuse-button-group[data-attached][data-orientation="vertical"] > .whatiuse-button:first-child:not(:last-child) { border-radius: var(--whatiuse-radius-control) var(--whatiuse-radius-control) 0 0; }

.whatiuse-button-group[data-attached][data-orientation="vertical"] > .whatiuse-button:last-child:not(:first-child) { border-radius: 0 0 var(--whatiuse-radius-control) var(--whatiuse-radius-control); }

.whatiuse-button-group__separator { display: block; align-self: stretch; flex: 0 0 auto; background: var(--whatiuse-separator); }

.whatiuse-button-group__separator[aria-orientation="vertical"] { width: 1px; min-height: 20px; margin: 4px 2px; }

.whatiuse-button-group__separator[aria-orientation="horizontal"] { height: 1px; min-width: 20px; margin: 2px 4px; }
}
